class Solution:
 def sumZero(self,n):
  out=[]
  for x in range(1,n//2+1):out.extend([x,-x])
  if n%2:out.append(0)
  return out

class Solution:
 def decompressRLElist(self,nums):
  out=[]
  for i in range(0,len(nums),2):out.extend([nums[i+1]]*nums[i])
  return out

class Solution:
 def arrayRankTransform(self,arr):
  rank={x:i+1 for i,x in enumerate(sorted(set(arr)))}
  return [rank[x] for x in arr]

class Solution:
 def numberOfSteps(self,num):
  steps=0
  while num:
   num=num//2 if num%2==0 else num-1;steps+=1
  return steps

class Solution:
 def smallerNumbersThanCurrent(self,nums):
  ordered=sorted(nums);rank={}
  for i,x in enumerate(ordered):rank.setdefault(x,i)
  return [rank[x] for x in nums]

from collections import Counter
class Solution:
 def sortString(self,s):
  c=Counter(s);out=[]
  while len(out)<len(s):
   for x in sorted(c):
    if c[x]:out.append(x);c[x]-=1
   for x in sorted(c,reverse=True):
    if c[x]:out.append(x);c[x]-=1
  return ''.join(out)

class Solution:
 def luckyNumbers(self,matrix):
  rowmins={min(row) for row in matrix};colmax={max(col) for col in zip(*matrix)}
  return sorted(rowmins&colmax)

class Solution:
 def createTargetArray(self,nums,index):
  out=[]
  for x,i in zip(nums,index):out.insert(i,x)
  return out
